"""Generate sitemap.xml and the link-preview (Open Graph) tags of public pages.

Run from the repository root: python3 .github/scripts/site_meta.py
The "Update Sitemap and Link Previews" workflow runs it on every push.

Preview tags are rebuilt from each page's own <title> and meta description
between the og-meta markers, so a blog post started by copying an older one
never keeps the old post's preview. Highlight pages are skipped: their tags
come from tools/share_cards.py.
"""
import glob
import html
import re
import subprocess

BASE = 'https://rpmenezes.github.io/'
SITE_CARD = BASE + 'og-card.png'
START = '<!-- og-meta:start (generated by .github/scripts/site_meta.py) -->'
END = '<!-- og-meta:end -->'
MAIN = ['index.html', 'research.html', 'scholarly-engagement.html', 'about.html',
        'videos.html', 'cv.html', 'blog/blog.html']


def url_for(path):
    return BASE + ('' if path == 'index.html' else path)


def head_value(src, pattern):
    m = re.search(pattern, src, re.S)
    return html.unescape(m.group(1).strip()) if m else ''


def og_block(path, src):
    title = head_value(src, r'<title>(.*?)</title>')
    desc = head_value(src, r'<meta name="description" content="(.*?)"\s*/?>')
    post = path.startswith('blog/posts/')
    # Blog posts use their square icon (small preview); other pages the site card.
    image = BASE + path[:-len('.html')] + '.png' if post else SITE_CARD
    tags = [('property', 'og:type', 'article' if post else 'website'),
            ('property', 'og:site_name', 'Ronaldo Menezes'),
            ('property', 'og:title', title),
            ('property', 'og:description', desc),
            ('property', 'og:url', url_for(path)),
            ('property', 'og:image', image),
            ('name', 'twitter:card', 'summary' if post else 'summary_large_image')]
    lines = [f'    <meta {k}="{n}" content="{html.escape(v, quote=True)}">' for k, n, v in tags if v]
    return '    ' + START + '\n' + '\n'.join(lines) + '\n    ' + END


def update_preview_tags(path):
    with open(path, encoding='utf-8') as f:
        src = f.read()
    block = og_block(path, src)
    pattern = re.compile(r'[ \t]*' + re.escape(START) + r'.*?' + re.escape(END), re.S)
    new = pattern.sub(lambda _: block, src) if pattern.search(src) \
        else src.replace('</head>', block + '\n</head>', 1)
    if new != src:
        with open(path, 'w', encoding='utf-8') as f:
            f.write(new)
        print('updated', path)


def lastmod(path):
    out = subprocess.run(['git', 'log', '-1', '--format=%cs', '--', path],
                         capture_output=True, text=True).stdout.strip()
    return f'<lastmod>{out}</lastmod>' if out else ''


def write_sitemap(pages):
    urls = '\n'.join(f'  <url><loc>{url_for(p)}</loc>{lastmod(p)}</url>' for p in pages)
    with open('sitemap.xml', 'w') as f:
        f.write('<?xml version="1.0" encoding="UTF-8"?>\n'
                '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
                + urls + '\n</urlset>\n')


if __name__ == '__main__':
    posts = sorted(glob.glob('blog/posts/*.html'), reverse=True)
    for p in MAIN + posts:
        update_preview_tags(p)
    # Unlisted pages, tools and the 404 page stay out of the sitemap.
    write_sitemap(MAIN + posts + sorted(glob.glob('highlights/*.html')))
